// Cache-aside with single-flight mutex protection
async function getProduct(id) {
  let cached = await redis.get(`product:${id}`);
  if (cached) return JSON.parse(cached);

  // Acquire lock to avoid thundering herd on database
  const lock = await redis.set(`lock:${id}`, '1', 'NX', 'EX', 5);
  if (lock) {
    const product = await db.products.findById(id);
    await redis.set(`product:${id}`, JSON.stringify(product), 'EX', 3600);
    return product;
  }
  // Wait and retry read from cache
  await sleep(50);
  return getProduct(id);
}
